import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"安装与更新","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1789979194000}'),i={name:"guide/getting-started.md"};function l(s,e,n,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="安装与更新" tabindex="-1">安装与更新 <a class="header-anchor" href="#安装与更新" aria-label="Permalink to &quot;安装与更新&quot;">​</a></h1><h2 id="安装前" tabindex="-1">安装前 <a class="header-anchor" href="#安装前" aria-label="Permalink to &quot;安装前&quot;">​</a></h2><p>准备一个可以正常访问的 Komari 服务。当前兼容验证基线为 Komari 1.5.0；更新已有主题前，保留旧主题包和站点配置。</p><h2 id="安装主题" tabindex="-1">安装主题 <a class="header-anchor" href="#安装主题" aria-label="Permalink to &quot;安装主题&quot;">​</a></h2><ol><li>打开 <a href="https://github.com/fanchengliu/komari-next-pro/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a>。</li><li>下载文件名以 <strong><code>-theme.zip</code></strong> 结尾的安装包。</li><li>在 Komari 管理后台的主题管理中上传 ZIP。</li><li>选择 <strong>Komari Next Pro</strong>，返回主页。</li><li>通过首次配置向导选择布局、背景、语言和显示内容。</li></ol><div class="tip custom-block"><p class="custom-block-title">选对安装包</p><p><code>-source.zip</code> 是完整源码，<code>-extension.zip</code> 是可选配套服务；GitHub 自动生成的 Source code ZIP 也不是主题安装包。</p></div><h2 id="从旧版升级" tabindex="-1">从旧版升级 <a class="header-anchor" href="#从旧版升级" aria-label="Permalink to &quot;从旧版升级&quot;">​</a></h2><p>3.x 的显示名称为 <strong>Komari Next Pro</strong>，内部安装标识仍为 <code>komari-ds</code>，以保留已有 DS 配置和扩展路由。</p><ul><li>已有 <strong>komari-ds 2.x</strong>：上传新版会更新同一安装标识的文件。建议先保留当前内置媒体副本，或把个人媒体保存到独立媒体库。</li><li>已有 <strong>Next Pro 2.x</strong>：安装 3.x 后在后台切换主题，旧主题与旧扩展先保留。两代扩展 API 不应直接混用。</li></ul><h2 id="刷新与回退" tabindex="-1">刷新与回退 <a class="header-anchor" href="#刷新与回退" aria-label="Permalink to &quot;刷新与回退&quot;">​</a></h2><p>更新后仍看到旧页脚或样式时，先使用 <code>Ctrl + Shift + R</code> 强制刷新。旧 Service Worker 仍缓存页面时，再清理该站点缓存。</p><p>需要回退时，重新导入保留的 DS 主题包，或切换回旧 Next Pro 主题。主题更新不会要求删除 Komari 数据库。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./appearance">设置外观与背景</a> · <a href="./network">查看网络历史</a> · <a href="./extension">按需安装扩展</a></p>',14)])])}const m=a(i,[["render",l]]);export{u as __pageData,m as default};
